// Claude Code SessionStart hook generated by agent-kit. Prints a short summary of unfinished
// workflow runs so the coordinator resumes them instead of starting over. Silent when there are none.
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

const root = process.env.CLAUDE_PROJECT_DIR || process.cwd();
const runsDir = join(root, ".agent-kit", "runs");

function activeRuns() {
  if (!existsSync(runsDir)) return [];
  const runs = [];
  for (const entry of readdirSync(runsDir, { withFileTypes: true })) {
    const file = join(runsDir, entry.name, "run.json");
    if (!entry.isDirectory() || !existsSync(file)) continue;
    try {
      const run = JSON.parse(readFileSync(file, "utf8"));
      if (["completed", "cancelled"].includes(run.state)) continue;
      const counts = {};
      for (const task of Object.values(run.tasks || {})) counts[task.state] = (counts[task.state] || 0) + 1;
      runs.push({ id: run.id, state: run.state, objective: run.objective, counts });
    } catch {
      runs.push({ id: entry.name, state: "unreadable", objective: "", counts: {} });
    }
  }
  return runs;
}

const runs = activeRuns();
if (runs.length) {
  const lines = runs.map((run) => {
    const counts = Object.entries(run.counts).map(([state, count]) => `${count} ${state}`).join(", ");
    return `- ${run.id} (${run.state}): ${run.objective || "no objective"} — ${counts}`;
  });
  process.stdout.write(
    [
      "agent-kit: unfinished workflow runs in this repository:",
      ...lines,
      "Resume with /retomar-workflow (it reconciles in-flight workers before redispatching) or check /status-workflow.",
    ].join("\n") + "\n"
  );
}
